svg.script:

function updateCalendarIcon() {
  const now = new Date();

  // Configuración para el nombre del día (abreviado, 3 letras, mayúsculas)
  const dayNameOptions = { weekday: 'short' };
  let dayName = now.toLocaleDateString('es-ES', dayNameOptions).toUpperCase();
  // Eliminar el punto si la abreviatura lo incluye (ej. "mié." -> "MIÉ")
  dayName = dayName.replace('.', ''); 

  // Número del día
  const dayNumber = now.getDate();

  // Actualizar el DOM del SVG
  document.getElementById('day-name').textContent = dayName;
  document.getElementById('day-number').textContent = dayNumber;
}

// Ejecutar al cargar
updateCalendarIcon();
